#include <array>
#include <cstddef>
#include <cstdint>
#include <vector>

namespace {
constexpr std::size_t QMAX=32, ROOTS=65, ARENA=16384, POOL=8192, LEVELS=16;
constexpr std::int64_t VMAX=1000000, SUMMAX=64000000;
struct Measure { std::int32_t count=0; std::int64_t sum=0; };
struct Tree { std::uint8_t kind=0,level=0,plen=0,slen=0; std::int32_t mid=-1; std::array<std::int32_t,4> pre{},suf{}; std::int32_t count=0; std::int64_t sum=0; };
struct Node { std::uint8_t arity=0; std::array<std::int32_t,3> child{}; std::int32_t count=0; std::int64_t sum=0; };
struct Root { std::int32_t tree=0,length=0; std::int64_t sum=0; };
struct View { bool found=false; std::int32_t item=0,tree=0; };
struct Split { bool found=false; std::int32_t item=0,left=0,right=0; };
struct Ctx {
    std::vector<Tree> trees; std::vector<Node> nodes; std::array<std::int32_t,LEVELS> empty{}; std::array<bool,LEVELS> empty_ready{}; bool failed=false;
    Ctx(){trees.reserve(POOL);nodes.reserve(POOL);empty.fill(-1);}
    std::int32_t tree(){if(trees.size()+nodes.size()>=ARENA||trees.size()>=POOL){failed=true;return 0;}trees.emplace_back();return (std::int32_t)trees.size()-1;}
    std::int32_t node(){if(trees.size()+nodes.size()>=ARENA||nodes.size()>=POOL){failed=true;return 0;}nodes.emplace_back();return (std::int32_t)nodes.size()-1;}
};
Measure addm(Measure a,Measure b){return {a.count+b.count,a.sum+b.sum};}
Measure refm(const Ctx&c,std::int32_t r){return r<0?Measure{1,-(std::int64_t)r-1}:Measure{c.nodes[(std::size_t)r].count,c.nodes[(std::size_t)r].sum};}
Measure treem(const Ctx&c,std::int32_t r){const auto&t=c.trees[(std::size_t)r];return {t.count,t.sum};}
std::int32_t empty(Ctx&c,std::uint8_t level){if(level>=LEVELS){c.failed=true;return 0;}if(c.empty_ready[level])return c.empty[level];auto id=c.tree();auto&t=c.trees[(std::size_t)id];t.kind=0;t.level=level;t.mid=-1;c.empty[level]=id;c.empty_ready[level]=true;return id;}
std::int32_t single(Ctx&c,std::uint8_t l,std::int32_t x){auto id=c.tree();auto&t=c.trees[(std::size_t)id];t.kind=1;t.level=l;t.plen=1;t.pre[0]=x;auto m=refm(c,x);t.count=m.count;t.sum=m.sum;return id;}
std::int32_t node(Ctx&c,const std::int32_t*x,std::uint8_t n){auto id=c.node();auto&z=c.nodes[(std::size_t)id];z.arity=n;Measure m{};for(std::uint8_t i=0;i<n;i++){z.child[i]=x[i];m=addm(m,refm(c,x[i]));}z.count=m.count;z.sum=m.sum;return id;}
std::int32_t deep(Ctx&c,std::uint8_t l,const std::int32_t*p,std::uint8_t pn,std::int32_t mid,const std::int32_t*s,std::uint8_t sn){if(!pn||!sn){c.failed=true;return empty(c,l);}auto id=c.tree();auto&t=c.trees[(std::size_t)id];t.kind=2;t.level=l;t.plen=pn;t.slen=sn;t.mid=mid;Measure m=treem(c,mid);for(std::uint8_t i=0;i<pn;i++){t.pre[i]=p[i];m=addm(m,refm(c,p[i]));}for(std::uint8_t i=0;i<sn;i++){t.suf[i]=s[i];m=addm(m,refm(c,s[i]));}t.count=m.count;t.sum=m.sum;return id;}
std::int32_t cons(Ctx&,std::uint8_t,std::int32_t,std::int32_t);
std::int32_t snoc(Ctx&,std::uint8_t,std::int32_t,std::int32_t);
std::int32_t from_items(Ctx&c,std::uint8_t l,const std::int32_t*x,std::uint8_t n){auto r=empty(c,l);for(std::uint8_t i=0;i<n;i++)r=snoc(c,l,r,x[i]);return r;}
std::int32_t cons(Ctx&c,std::uint8_t l,std::int32_t x,std::int32_t id){auto t=c.trees[(std::size_t)id];if(!t.kind)return single(c,l,x);if(t.kind==1){std::int32_t p[1]={x},s[1]={t.pre[0]};return deep(c,l,p,1,empty(c,l+1),s,1);}if(t.plen<4){std::int32_t p[4]={x};for(std::uint8_t i=0;i<t.plen;i++)p[i+1]=t.pre[i];return deep(c,l,p,t.plen+1,t.mid,t.suf.data(),t.slen);}std::int32_t g[3]={t.pre[1],t.pre[2],t.pre[3]},p[2]={x,t.pre[0]};return deep(c,l,p,2,cons(c,l+1,node(c,g,3),t.mid),t.suf.data(),t.slen);}
std::int32_t snoc(Ctx&c,std::uint8_t l,std::int32_t id,std::int32_t x){auto t=c.trees[(std::size_t)id];if(!t.kind)return single(c,l,x);if(t.kind==1){std::int32_t p[1]={t.pre[0]},s[1]={x};return deep(c,l,p,1,empty(c,l+1),s,1);}if(t.slen<4){auto s=t.suf;s[t.slen]=x;return deep(c,l,t.pre.data(),t.plen,t.mid,s.data(),t.slen+1);}std::int32_t g[3]={t.suf[0],t.suf[1],t.suf[2]},s[2]={t.suf[3],x};return deep(c,l,t.pre.data(),t.plen,snoc(c,l+1,t.mid,node(c,g,3)),s,2);}
View viewl(Ctx&c,std::uint8_t l,std::int32_t id){auto t=c.trees[(std::size_t)id];if(!t.kind)return {false,0,id};if(t.kind==1)return {true,t.pre[0],empty(c,l)};auto x=t.pre[0];std::int32_t r;if(t.plen>1)r=deep(c,l,t.pre.data()+1,t.plen-1,t.mid,t.suf.data(),t.slen);else{auto v=viewl(c,l+1,t.mid);if(!v.found)r=from_items(c,l,t.suf.data(),t.slen);else{auto n=c.nodes[(std::size_t)v.item];r=deep(c,l,n.child.data(),n.arity,v.tree,t.suf.data(),t.slen);}}return {true,x,r};}
View viewr(Ctx&c,std::uint8_t l,std::int32_t id){auto t=c.trees[(std::size_t)id];if(!t.kind)return {false,0,id};if(t.kind==1)return {true,t.pre[0],empty(c,l)};auto x=t.suf[t.slen-1];std::int32_t r;if(t.slen>1)r=deep(c,l,t.pre.data(),t.plen,t.mid,t.suf.data(),t.slen-1);else{auto v=viewr(c,l+1,t.mid);if(!v.found)r=from_items(c,l,t.pre.data(),t.plen);else{auto n=c.nodes[(std::size_t)v.item];r=deep(c,l,t.pre.data(),t.plen,v.tree,n.child.data(),n.arity);}}return {true,x,r};}
std::int32_t deepL(Ctx&c,std::uint8_t l,const std::int32_t*p,std::uint8_t pn,std::int32_t m,const std::int32_t*s,std::uint8_t sn){if(pn)return deep(c,l,p,pn,m,s,sn);auto v=viewl(c,l+1,m);if(!v.found)return from_items(c,l,s,sn);auto n=c.nodes[(std::size_t)v.item];return deep(c,l,n.child.data(),n.arity,v.tree,s,sn);}
std::int32_t deepR(Ctx&c,std::uint8_t l,const std::int32_t*p,std::uint8_t pn,std::int32_t m,const std::int32_t*s,std::uint8_t sn){if(sn)return deep(c,l,p,pn,m,s,sn);auto v=viewr(c,l+1,m);if(!v.found)return from_items(c,l,p,pn);auto n=c.nodes[(std::size_t)v.item];return deep(c,l,p,pn,v.tree,n.child.data(),n.arity);}
std::uint8_t group(Ctx&c,std::uint8_t l,const std::int32_t*x,std::uint8_t n,std::int32_t*out){std::uint8_t k=0,p=0;while(p<n){auto rem=(std::uint8_t)(n-p);auto take=(std::uint8_t)((rem==2||rem==4)?2:3);if(rem==1){c.failed=true;return k;}out[k++]=node(c,x+p,take);p+=take;}return k;}
std::int32_t append3(Ctx&c,std::uint8_t l,std::int32_t a,const std::int32_t*x,std::uint8_t xn,std::int32_t b){auto A=c.trees[(std::size_t)a],B=c.trees[(std::size_t)b];if(!A.kind){auto r=b;for(int i=(int)xn-1;i>=0;i--)r=cons(c,l,x[i],r);return r;}if(!B.kind){auto r=a;for(std::uint8_t i=0;i<xn;i++)r=snoc(c,l,r,x[i]);return r;}if(A.kind==1){auto r=b;for(int i=(int)xn-1;i>=0;i--)r=cons(c,l,x[i],r);return cons(c,l,A.pre[0],r);}if(B.kind==1){auto r=a;for(std::uint8_t i=0;i<xn;i++)r=snoc(c,l,r,x[i]);return snoc(c,l,r,B.pre[0]);}std::int32_t all[16],ns[8];std::uint8_t n=0;for(std::uint8_t i=0;i<A.slen;i++)all[n++]=A.suf[i];for(std::uint8_t i=0;i<xn;i++)all[n++]=x[i];for(std::uint8_t i=0;i<B.plen;i++)all[n++]=B.pre[i];auto nn=group(c,l,all,n,ns);auto m=append3(c,l+1,A.mid,ns,nn,B.mid);return deep(c,l,A.pre.data(),A.plen,m,B.suf.data(),B.slen);}
bool pred(int mode,std::int64_t target,Measure m){return mode==0?m.count>target:m.sum>=target;}
Split splitTree(Ctx&c,std::int32_t id,Measure acc,int mode,std::int64_t target){auto t=c.trees[(std::size_t)id];if(!t.kind)return {false,0,0,id};if(t.kind==1){if(pred(mode,target,addm(acc,refm(c,t.pre[0]))))return {true,t.pre[0],empty(c,t.level),empty(c,t.level)};return {false,0,id,empty(c,t.level)};}Measure cur=acc;std::uint8_t pn=0;std::int32_t ps[4];for(std::uint8_t i=0;i<t.plen;i++){cur=addm(cur,refm(c,t.pre[i]));ps[pn++]=t.pre[i];if(pred(mode,target,cur)){auto l=from_items(c,t.level,ps,pn-1);auto r=deepL(c,t.level,t.pre.data()+pn,t.plen-pn,t.mid,t.suf.data(),t.slen);return {true,t.pre[i],l,r};}}Measure ap=acc;for(std::uint8_t i=0;i<t.plen;i++)ap=addm(ap,refm(c,t.pre[i]));auto mm=treem(c,t.mid);Measure through=addm(ap,mm);if(pred(mode,target,through)){auto sm=splitTree(c,t.mid,ap,mode,target);if(!sm.found){c.failed=true;return {false,0,id,empty(c,t.level)};}auto nd=c.nodes[(std::size_t)sm.item];Measure ca=addm(ap,treem(c,sm.left));std::int32_t before[3],after[3],pivot=0;std::uint8_t nb=0,na=0;bool found=false;for(std::uint8_t i=0;i<nd.arity;i++){auto next=addm(ca,refm(c,nd.child[i]));if(!found&&pred(mode,target,next)){pivot=nd.child[i];found=true;}else if(!found){before[nb++]=nd.child[i];ca=next;}else after[na++]=nd.child[i];}if(!found){c.failed=true;return {false,0,id,empty(c,t.level)};}return {true,pivot,deepR(c,t.level,t.pre.data(),t.plen,sm.left,before,nb),deepL(c,t.level,after,na,sm.right,t.suf.data(),t.slen)};}cur=through;std::int32_t before[4];std::uint8_t nb=0;for(std::uint8_t i=0;i<t.slen;i++){cur=addm(cur,refm(c,t.suf[i]));before[nb++]=t.suf[i];if(pred(mode,target,cur)){auto l=deepR(c,t.level,t.pre.data(),t.plen,t.mid,before,nb-1);auto r=from_items(c,t.level,t.suf.data()+nb,t.slen-nb);return {true,t.suf[i],l,r};}}return {false,0,id,empty(c,t.level)};}
std::int64_t val(std::int32_t x){return -(std::int64_t)x-1;}
void put(std::uint8_t*p,std::size_t off,std::int64_t v){auto bits=(std::uint64_t)v;for(int i=0;i<8;i++)p[off+i]=(std::uint8_t)(bits>>(8*i));}
}

extern "C" std::int64_t measured_finger_tree_sequence(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap){
 if(!in||len<2||len>195)return -1;auto n0=in[0];if(n0<0||n0>32)return -1;auto n=(std::size_t)n0;if(len<n+2)return -1;auto qv=in[n+1];if(qv<1||qv>32)return -1;auto q=(std::size_t)qv;if(len!=n+2+5*q||len>194)return -1;
 Ctx c;auto t=empty(c,0);for(std::size_t i=0;i<n;i++){auto v=in[1+i];if(v<0||v>VMAX)return -1;t=snoc(c,0,t,(std::int32_t)(-v-1));}if(c.failed)return -1;std::array<Root,ROOTS> roots{};auto m=treem(c,t);if(m.count>64||m.sum>SUMMAX)return -1;roots[0]={t,m.count,m.sum};std::size_t nr=1,at=n+2;std::array<std::int64_t,QMAX*7> records{};
 for(std::size_t op=0;op<q;op++){auto tag=in[at],aa=in[at+1],bb=in[at+2],x=in[at+3],y=in[at+4];at+=5;if(tag<0||tag>6||aa<0||(std::size_t)aa>=nr||nr>=ROOTS)return -1;auto a=(std::size_t)aa;auto source=roots[a].tree;std::int32_t res=0,res2=0,right=-1;std::int64_t aux=-1;bool two=false;
  if(tag<=1){if(bb!=-1||y!=-1||x<0||x>VMAX||roots[a].length>=64||roots[a].sum+x>SUMMAX)return -1;auto item=(std::int32_t)(-x-1);res=tag==0?cons(c,0,item,source):snoc(c,0,source,item);}
  else if(tag<=3){if(bb!=-1||x!=-1||y!=-1||roots[a].length==0)return -1;auto v=tag==2?viewl(c,0,source):viewr(c,0,source);if(!v.found)return -1;res=v.tree;aux=val(v.item);}
  else if(tag==4){if(bb<0||(std::size_t)bb>=nr||x!=-1||y!=-1)return -1;if(roots[a].length+roots[(std::size_t)bb].length>64||roots[a].sum+roots[(std::size_t)bb].sum>SUMMAX)return -1;res=append3(c,0,source,nullptr,0,roots[(std::size_t)bb].tree);}
  else{if(bb!=-1||y!=-1||(tag==5&&(x<0||x>roots[a].length))||(tag==6&&(x<1||x>SUMMAX)))return -1;auto s=splitTree(c,source,{},tag==5?0:1,x);if(s.found){if(tag==5){res=s.left;res2=cons(c,0,s.item,s.right);aux=x;}else{res=snoc(c,0,s.left,s.item);res2=s.right;aux=treem(c,res).count;}}else{res=source;res2=empty(c,0);aux=tag==5?x:-1;}two=true;}
  if(c.failed)return -1;auto lm=treem(c,res);if(lm.count>64||lm.sum>SUMMAX)return -1;auto left=(std::int32_t)nr;roots[nr++]={res,lm.count,lm.sum};std::int32_t rn=-1,rl=-1;std::int64_t rs=-1;if(two){if(nr>=ROOTS)return -1;auto rm=treem(c,res2);if(rm.count>64||rm.sum>SUMMAX)return -1;rn=(std::int32_t)nr;rl=rm.count;rs=rm.sum;roots[nr++]={res2,rm.count,rm.sum};}auto o=7*op;records[o]=left;records[o+1]=lm.count;records[o+2]=lm.sum;records[o+3]=rn;records[o+4]=rl;records[o+5]=rs;records[o+6]=aux;
 }
 auto bytes=56*q;if(!out||cap<bytes)return -2;std::array<std::uint8_t,1792> staged{};for(std::size_t i=0;i<q*7;i++)put(staged.data(),i*8,records[i]);for(std::size_t i=0;i<bytes;i++)out[i]=staged[i];return (std::int64_t)bytes;
}
